 [0,.25,.5,.75,1].forEach(t=>{const x=351+t*386;F.line(chart,x,247,x,516,C.grey,.6).setAttribute('stroke-opacity',.22);w(chart,'r2-tick'+t,x-28,521,56,34,String(t),String(t),20,C.grey);});
 panel(p,872,236,318,306,C.teal);const text=w(p,'r2-explanation',888,251,286,274,'','',29,C.teal);
 buttons(v,[['Число минимумов','Minimum count'],['Успех SA','SA success']],i=>d.set({phase:Math.max(1,s.phase),target:i}),285,561,554);
