add('qalign-detail-fdc',['FDC: ведёт ли энергия к правильному ответу?','FDC: does energy guide us toward an optimum?'],[
 ['FDC сопоставляет энергию ответа и расстояние до выбранного глобального оптимума. Каждая точка — одна из 720 перестановок. По вертикали энергия, ниже лучше; по горизонтали расстояние Кендалла. Совпавшие точки лежат друг на друге.','FDC compares answer energy and distance to a selected global optimum. Each dot is one of 720 permutations. Vertical: energy, lower is better. Horizontal: Kendall distance. Coincident observations overlap.'],
 ['В коде расстояние Кендалла — число инверсий относительно выбранной перестановки, то есть минимальное число соседних обменов порядка. Это не минимальное число произвольных обменов SA. Например, обращение шести позиций имеет 15 инверсий, хотя произвольными обменами исправляется за три хода.','Code Kendall distance counts inversions relative to the selected permutation: the minimum number of adjacent-order swaps. It is not SA’s arbitrary-swap distance. Reversing six positions has 15 inversions but takes only three arbitrary swaps to undo.'],
 ['FDC — корреляция Пирсона между расстояниями и энергиями. Положительная корреляция означает тенденцию: ближе к оптимуму — ниже энергия. Для этого ER-примера FDC=0.049, почти ноль. Рисунок не подтверждает сильную общую воронку. Ползунок позволяет увидеть расстояние и энергию конкретного ответа.','FDC is Pearson correlation between distances and energies. Positive correlation suggests closer answers tend to have lower energy. This ER example gives FDC=0.049, close to zero. It does not support a strong global funnel. The slider inspects a particular answer’s distance and energy.'],
 ['Здесь четыре глобальных оптимума. Кнопка «Ближайший из 4» показывает дополнительную проверку: минимальное расстояние Кендалла до любого оптимума. Это другой показатель, не исходная функция FDC ноутбука. Смена опорного ответа или метрики расстояния способна менять вывод; их нужно объявлять явно.','There are four global optima. “Nearest of 4” adds a sensitivity check: minimum Kendall distance to any optimum. This differs from the notebook’s original FDC function. Reference choice and distance convention can change conclusions and must be explicit.']
],[[['Это пространственные координаты графов?','Are these graph drawing coordinates?'],['Нет. Оси показывают вычисленные расстояние между ответами и энергию. Координаты узлов исходных сетей здесь не используются.','No. The axes show computed answer distance and energy. Input-network drawing coordinates are irrelevant here.']]],ctx=>{
 const title=['FDC: ведёт ли энергия к правильному ответу?','FDC: does energy guide us toward an optimum?'],v=stage(ctx,title),p=v.p,s={phase:0,reference:0,index:0};let d;
 const x=dist=>145+dist/15*565,y=e=>455-(e+28)/14*199,points=Z.energies.map((e,i)=>F.dot(p,x(M.fdc.kendallDistances[i]),y(e),3,C.blue));points.forEach(el=>el.setAttribute('fill-opacity',.22));
 F.line(p,145,455,715,455,C.grey,1.2);F.line(p,145,256,145,455,C.grey,1.2);
 [0,5,10,15].forEach(t=>w(p,'fdc-x'+t,x(t)-22,460,44,34,String(t),String(t),20,C.grey));[-28,-21,-14].forEach(e=>w(p,'fdc-y'+e,78,y(e)-20,64,39,String(e),String(e),21,C.grey));
 w(p,'fdc-x-label',123,502,617,43,'Расстояние Кендалла','Kendall distance',25,C.grey);w(p,'fdc-y-label',95,184,657,62,'Энергия ответа · все 720 перестановок','Answer energy · all 720 permutations',26,C.blue);
 const selected=F.dot(p,x(0),y(-28),8,C.gold),summary=w(p,'fdc-reference',836,168,348,65,'','',27,C.gold);
 panel(p,817,247,370,231,C.teal);const detail=w(p,'fdc-current',836,265,332,196,'','',29,C.teal);
 buttons(v,[['Один оптимум','One optimum'],['Ближайший из 4','Nearest of 4']],reference=>d.set({reference,phase:3}),801,499,404);
 const control=slider(v,['Ответ: индекс в списке','Answer: list index'],0,719,0,1,index=>d.set({index}),169,553,535);
 function paint(){const ref=Math.round(s.reference),i=Math.round(s.index),dist=ref?M.fdc.nearestDistances:M.fdc.kendallDistances,value=ref?M.fdc.nearestValue:M.fdc.value;points.forEach((el,j)=>F.pos(el,x(dist[j]),y(Z.energies[j])));F.pos(selected,x(dist[i]),y(Z.energies[i]));summary.setText('FDC = '+value.toFixed(3));detail.setText(tr('Ответ '+i+'\nE = '+Z.energies[i]+'\nРасстояние = '+dist[i]+'\n'+(ref?'До любого оптимума':'До оптимума #'+M.fdc.referenceId),'Answer '+i+'\nE = '+Z.energies[i]+'\nDistance = '+dist[i]+'\n'+(ref?'To any optimum':'To optimum #'+M.fdc.referenceId)));control.input.value=i;control.output.textContent=i;stat(v,s,{fdc:value,fdcReference:ref?'nearest':'first',answerId:i,answerDistance:dist[i],answerEnergy:Z.energies[i]});}
 d=steps(ctx,v,s,paint,['Сравним энергию каждого ответа с расстоянием до оптимума.','Compare each answer’s energy with its distance to an optimum.'],[
 {patch:{phase:1,index:138},caption:['Кендалл считает инверсии; SA использует другой набор обменов.','Kendall counts inversions; SA uses a different swap convention.']},
 {patch:{phase:2,index:M.fdc.referenceId},caption:['Для выбранного оптимума FDC почти нулевая: 0.049.','For the selected optimum, FDC is close to zero: 0.049.']},
 {patch:{phase:3,reference:1},caption:['Учитывая все четыре оптимума, получаем другой показатель.','Accounting for all four optima gives a different diagnostic.']}]);return v.root;
},true);

add('qalign-detail-walk',['Случайное блуждание: память энергии','Random walk: energy memory'],[
 ['Это отдельный метод диагностики, а не SA. Из случайной перестановки делаем случайный обмен на каждом шаге и всегда переходим, даже если энергия выросла. Никакой температуры или проверки улучшения здесь нет. Показана настоящая траектория из 800 обменов, seed=105.','This is a diagnostic method, separate from SA. Start from a random permutation, propose random swaps and always move, even when energy rises. There is no temperature or improvement test. This is the actual 800-swap trajectory with seed=105.'],
 ['Записываем энергии E₀…E₈₀₀. График показывает окно из 80 обменов; кнопки меняют окно, сохраняя исходную траекторию. Сравниваем соседние во времени значения: похожи ли Eₜ и Eₜ₊₁? Последовательные состояния не являются независимыми наблюдениями.','Record E₀…E₈₀₀. The chart shows a window of 80 swaps; buttons change the window within the same recorded trajectory. Compare adjacent values: are Eₜ and Eₜ₊₁ similar? Successive states are not independent observations.'],
 ['Код использует ρ(1)=Σₜ(Eₜ−μ)(Eₜ₊₁−μ)/(800·Var(E)), где μ и Var посчитаны по всем 801 значениям. Здесь ρ(1)=0.350. Это умеренная связь энергий соседних шагов при данном правиле ходов; она не является шансом найти оптимум.','The code estimates ρ(1)=Σₜ(Eₜ−μ)(Eₜ₊₁−μ)/(800·Var(E)), using the mean and variance of all 801 values. Here ρ(1)=0.350. This describes energy dependence between consecutive moves under this move rule, not the chance of finding an optimum.'],
 ['При 0<ρ<1 ноутбук вычисляет ℓ=−1/lnρ≈0.954 шага. Это сводная оценка из лага 1, а не доказательство экспоненциального спада всей автокорреляции. Блуждание не требует n! перебора, но стоимость оценки одной энергии и ошибка конечной выборки сохраняются. FDC и точные барьеры в текущем коде используют полный перебор.','For 0<ρ<1 the notebook computes ℓ=−1/lnρ≈0.954 steps. This lag-1 summary does not establish exponential decay of the full autocorrelation. The walk avoids n! enumeration, but energy-evaluation cost and finite-sample error remain. Current FDC and exact barrier code use enumeration.']
],[[['Блуждание пытается найти лучший ответ?','Does the walk try to find an optimum?'],['Нет. Оно измеряет, как меняется энергия по случайным ходам, без предпочтения улучшений.','No. It measures energy changes along random moves without favoring improvements.']]],ctx=>{
 const title=['Случайное блуждание: память энергии','Random walk: energy memory'],v=stage(ctx,title),p=v.p,s={phase:0,start:0};let d;
 const x=t=>139+t/80*552,y=e=>455-(e+28)/14*218,path=F.path(p,[],C.blue,2.2),range=w(p,'walk-range',112,162,603,65,'','',27,C.blue);
 F.line(p,139,455,695,455,C.grey,1.2);[-28,-21,-14].forEach(e=>w(p,'walk-energy'+e,71,y(e)-20,65,40,String(e),String(e),21,C.grey));
 const ticks=[0,40,80].map(t=>w(p,'walk-tick'+t,x(t)-36,460,72,37,'','',21,C.grey));
 w(p,'walk-x-label',142,499,550,44,'Шаги случайного блуждания','Random-walk steps',25,C.grey);
 panel(p,814,229,373,313,C.teal);const text=w(p,'walk-explanation',833,245,335,281,'','',30,C.teal);
 buttons(v,[['Начало','Start'],['Середина','Middle'],['Конец','End']],i=>d.set({start:[0,360,720][i]}),256,562,474);
 function paint(){const start=Math.max(0,Math.min(720,Math.round(s.start))),values=M.walk.energies.slice(start,start+81);path.setAttribute('d',values.map((e,i)=>(i?'L':'M')+x(i)+','+y(e)).join(' '));range.setText(tr('Энергия · шаги '+start+'…'+(start+80),'Energy · steps '+start+'…'+(start+80)));ticks.forEach((label,i)=>label.setText(String(start+i*40)));text.setText(s.phase<1?tr('Случайный обмен.\nВсегда переходим.','Random swap.\nAlways move.'):s.phase<2?tr('Не выбираем\nлучшие шаги.\nЗаписываем энергию.','Do not favor\nbetter moves.\nRecord energy.'):s.phase<3?'ρ(1) = '+M.walk.rho.toFixed(3)+'\n'+tr('Сходство энергий\nсоседних шагов','Energy similarity\nof consecutive moves'):'ℓ = −1 / ln ρ\n= '+M.walk.correlationLength.toFixed(3)+tr(' шага',' steps'));stat(v,s,{walkStart:start,walkRho:M.walk.rho,walkLength:M.walk.correlationLength});}
 d=steps(ctx,v,s,paint,['Каждый предложенный случайный обмен принимается.','Every proposed random swap is accepted.'],[
 {patch:{phase:1,start:360},caption:['Следим за энергией, не пытаясь её уменьшать.','Track energy without trying to lower it.']},
 {patch:{phase:2,start:720},caption:['По полной траектории считаем автокорреляцию: ρ(1) = 0.350.','Compute full-trajectory autocorrelation: ρ(1) = 0.350.']},
 {patch:{phase:3},caption:['Эта диагностика работает без полного перебора ответов.','This diagnostic works without enumerating all answers.']}]);return v.root;
},true);

add('qalign-detail-minimax',['Барьер: самый низкий возможный перевал','Barrier: the lowest possible pass'],[
 ['Барьер зависит от стартового состояния, конечного состояния и разрешённых ходов. Для каждой цепочки обменов берём максимальную энергию на пути; среди всех путей выбираем наименьшую такую высоту. Это minimax, а не путь с наименьшей суммой энергий или наименьшим числом ходов.','A barrier depends on the start, destination and allowed moves. Take each path’s maximum energy, then minimize that maximum across paths. This is minimax, not minimum total energy or fewest moves.'],
 ['Для выбранного локального минимума #138 с E=−26 минимальный перевал к глобальному оптимуму равен −24. Показанная точная цепочка #138→#380→#382 имеет энергии −26→−24→−28. Каждый переход — один разрешённый обмен двух назначений. Линии соединяют дискретные состояния и не задают энергию промежуточных физических конфигураций.','For local minimum #138 at E=−26, the lowest pass to a global optimum is −24. The exact path #138→#380→#382 has energies −26→−24→−28. Every transition is one permitted swap. Lines connect discrete states and do not specify energies of intermediate physical configurations.'],
 ['Вперёд барьер равен −24−(−26)=2. Обратно между этими же состояниями — −24−(−28)=4. Высота перевала одна, но цена подъёма относительно старта разная. Код Phase 1 хранит оба направления. Нулевой барьер тоже возможен для плато и путей без подъёма.','The forward barrier is −24−(−26)=2. In reverse between these states it is −24−(−28)=4. The pass energy is identical, but the climb relative to the starting energy differs. Phase 1 records both directions. Plateaus and paths without a climb may have zero barriers.'],
 ['Exact minimax в ноутбуке перебирает пространство перестановок и запускает модифицированный Dijkstra от каждого локального минимума. Это ограничено малыми n. Высота барьера полезна для описания SA, но сама не доказывает квантовое преимущество: важны кодирование, ширина барьера, выбранный квантовый метод, шум и честный классический baseline.','Notebook exact minimax enumerates permutations and runs modified Dijkstra from each local minimum. This is limited to small n. Height helps describe SA but does not establish quantum advantage: encoding, barrier width, quantum method, noise and a fair classical baseline also matter.']
],[[['Можно по барьеру 2 предсказать успех SA?','Does a barrier of 2 determine SA success?'],['Нет. Вероятность одного подъёма зависит от температуры; достижение перевала зависит ещё от доступных путей и бюджета.','No. One climb’s acceptance depends on temperature; reaching the pass also depends on available paths and budget.']], [['3D-поверхность ноутбука — точная геометрия?','Is the notebook’s 3D surface exact geometry?'],['MDS сжимает расстояния между перестановками до двух координат с искажением, а энергия даёт третью. Поверхность для наглядности не является непрерывным физическим потенциалом или точной картой swap-соседства.','MDS compresses permutation distances into two distorted coordinates; energy supplies the third. The illustration is not a continuous physical potential or exact swap-neighborhood map.']]],ctx=>{
 const title=['Барьер: самый низкий возможный перевал','Barrier: the lowest possible pass'],v=stage(ctx,title),p=v.p,s={phase:0,progress:0},view=barrierView(v,{compact:true});
 w(p,'minimax-path-label',582,162,608,70,'Путь: #138 → #380 → #382','Path: #138 → #380 → #382',26,C.blue);
 panel(p,910,239,276,257,C.teal);const definition=w(p,'minimax-definition',926,255,244,224,'','',29,C.teal);
 const calculation=w(p,'minimax-calculation',111,560,1057,48,'','',30,C.gold);
 function paint(){view.paint(s.progress);definition.setText(s.phase<1?tr('Ищем путь\nс самым низким\nперевалом','Find the path\nwith the lowest\npass'):s.phase<3?tr('Перевал:\nE = −24\nВперёд: +2','Pass:\nE = −24\nForward: +2'):tr('Тот же перевал.\nОбратно: +4','Same pass.\nReverse: +4'));calculation.setText(s.phase<3?tr('Δ вперёд = −24 − (−26) = 2','Δ forward = −24 − (−26) = 2'):tr('Δ обратно = −24 − (−28) = 4','Δ reverse = −24 − (−28) = 4'));stat(v,s,{minimaxSaddle:-24,forwardBarrier:2,reverseBarrier:4});}
 steps(ctx,v,s,paint,['Нужен самый низкий перевал среди всех допустимых путей.','Find the lowest pass across all allowed paths.'],[
 {patch:{phase:1,progress:1},caption:['Самая высокая энергия на этом minimax-пути — −24.','The highest energy on this minimax path is −24.']},
 {patch:{phase:2,progress:2},caption:['Из −26 нужно подняться на 2, чтобы попасть в −28.','From −26, climb by 2 to reach −28.']},
 {patch:{phase:3,progress:0},caption:['В обратном направлении подъём от −28 равен 4.','In reverse, the climb from −28 is 4.']}]);return v.root;
},true);
